import{_ as n,o as a,c as o,a2 as r}from"./chunks/framework.iWwp2X7T.js";const u=JSON.parse('{"title":"LAN & QR pairing","description":"Mobile Inspector development documentation · LAN & QR pairing","frontmatter":{"title":"LAN & QR pairing","description":"Mobile Inspector development documentation · LAN & QR pairing"},"headers":[],"relativePath":"en/guide/connection-lan.md","filePath":"en/guide/connection-lan.md"}'),t={name:"en/guide/connection-lan.md"};function i(s,e,c,d,l,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="lan-qr-pairing" tabindex="-1">LAN &amp; QR pairing <a class="header-anchor" href="#lan-qr-pairing" aria-label="Permalink to &quot;LAN &amp; QR pairing&quot;">​</a></h1><h2 id="prepare-a-route" tabindex="-1">Prepare a route <a class="header-anchor" href="#prepare-a-route" aria-label="Permalink to &quot;Prepare a route&quot;">​</a></h2><p>Start the local viewer and open <strong>Connect device</strong>. Choose a registered project or the explicit unassigned local-only option. Select the computer&#39;s LAN IPv4 address deliberately when multiple adapters exist. A loopback address cannot serve a phone QR. Check same-LAN routing and firewall rules.</p><h2 id="scan-confirm-record" tabindex="-1">Scan, confirm, record <a class="header-anchor" href="#scan-confirm-record" aria-label="Permalink to &quot;Scan, confirm, record&quot;">​</a></h2><p>Click <strong>Generate connection QR</strong> to open the selected listener. The locally generated QR contains a 30-minute upload capability. Keep it off screenshots, logs and prompts.</p><p>In the internal diagnostic app, choose <strong>Scan</strong>. Camera permission starts only here. The camera stops after recognition, before validation and confirmation. Check endpoint, expiry and truncated fingerprint; choose <strong>Confirm configuration</strong>. “Configured; connection verified when sending” is configuration status, not receipt proof. Start recording separately and verify a received event in the viewer.</p><p>Manual pairing JSON remains available when scanning is denied or unavailable. Background, cancel, panel disposal and account/environment changes invalidate pending scans. Hosts must clear/disconnect on account changes.</p><h2 id="trust-and-revocation" tabindex="-1">Trust and revocation <a class="header-anchor" href="#trust-and-revocation" aria-label="Permalink to &quot;Trust and revocation&quot;">​</a></h2><p>H5 scanning needs a secure context. H5/WeChat/HarmonyOS ingestion needs system-trusted HTTPS; WeChat domain configuration still applies. Do not install a CA or weaken business TLS as a workaround. Native diagnostic pinning is a separate policy.</p><p>Hiding a QR or closing a dialog does not revoke its capability. Use <strong>Revoke</strong>, clear, or expiry. Changing address/project/transport removes displayed pairing data. <a href="./connection-usb">USB</a> remains available for the supported wired iPhone flow.</p>',10)])])}const h=n(t,[["render",i]]);export{u as __pageData,h as default};
